INSERT OR REPLACE INTO units (id, type, number, name, racgp_url, blurb, rationale, competencies, learning_strategies, guiding_topics, case_example, guidelines, materials) VALUES
(1, 'core', 1, 'Communication and the patient–doctor relationship', 'https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/1-communication-and-the-patient-doctor-relationship', 'Domain 1: consulting effectively, health education, cultural safety in communication, holistic patient-centred care.', 'Domain 1: consulting effectively, health education, cultural safety in communication, holistic patient-centred care.', '[{"domain": "D1 Communication and the patient-doctor relationship", "outcome": "Communicate clearly, respectfully and effectively; use health education and culturally safe communication; provide holistic, patient-centred care."}, {"domain": "D2 Applied professional knowledge and skills", "outcome": "Take a timely history, perform a relevant examination, form differentials, select and interpret investigations, reason clinically, prescribe safely and manage uncertainty."}, {"domain": "D3 Population health and the context of general practice", "outcome": "Apply epidemiology to screening and management, use resources sustainably, manage public health risks, and promote health equity."}, {"domain": "D4 Professional and ethical role", "outcome": "Practise ethically with duty of care, maintain professional conduct and boundaries, care for your own health, and contribute to teaching and quality."}, {"domain": "D5 Organisational and legal dimensions", "outcome": "Maintain accurate records, privacy and consent; work within medico-legal, quality and safety frameworks; manage time, priorities and systems of care."}]', '[{"context": "On your own", "text": "Read this unit''s RACGP page and its primary guideline; list the last five patients from your practice who fit this unit and check your management against the guideline."}, {"context": "With your supervisor", "text": "Bring two recent cases from this unit to your tutorial; map your reasoning to the competency framework and ask for specific feedback."}, {"context": "In a small group", "text": "Run a case-based discussion or role-play: one member presents a case from this unit, the group works the differential and management, then compare with the guideline."}, {"context": "With a non-medical person", "text": "Explain one core concept from this unit (e.g., why we screen, how the treatment works) in plain language to a friend or family member - teach-back tests your own understanding."}]', '["Consultation models and structuring the consultation", "Open and closed questioning; ICE (ideas, concerns, expectations)", "Health literacy and plain-language explaining", "Breaking bad news (SPIKES)", "Motivational interviewing and behaviour change", "Shared decision making and patient-centred care", "Difficult consultations: anger, tears, silence", "Telehealth consultation skills"]', '', '[{"title": "RACGP Curriculum unit page", "tier": 1, "url": "https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/1-communication-and-the-patient-doctor-relationship", "source": "RACGP Curriculum unit page"}]', '[{"label": "RACGP patient-centred consulting models (course) gplearning", "url": "https://www.racgp.org.au/education/professional-development/online-learning/gplearning", "kind": "course", "source": "RACGP patient-centred consulting models (course) gplearning"}]'),
(2, 'core', 2, 'Applied professional knowledge and skills', 'https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/2-applied-professional-knowledge-and-skills', 'Domain 2: history, examination, differential diagnoses, investigations, clinical reasoning, prescribing, procedures, uncertainty.', 'Domain 2: history, examination, differential diagnoses, investigations, clinical reasoning, prescribing, procedures, uncertainty.', '[{"domain": "D1 Communication and the patient-doctor relationship", "outcome": "Communicate clearly, respectfully and effectively; use health education and culturally safe communication; provide holistic, patient-centred care."}, {"domain": "D2 Applied professional knowledge and skills", "outcome": "Take a timely history, perform a relevant examination, form differentials, select and interpret investigations, reason clinically, prescribe safely and manage uncertainty."}, {"domain": "D3 Population health and the context of general practice", "outcome": "Apply epidemiology to screening and management, use resources sustainably, manage public health risks, and promote health equity."}, {"domain": "D4 Professional and ethical role", "outcome": "Practise ethically with duty of care, maintain professional conduct and boundaries, care for your own health, and contribute to teaching and quality."}, {"domain": "D5 Organisational and legal dimensions", "outcome": "Maintain accurate records, privacy and consent; work within medico-legal, quality and safety frameworks; manage time, priorities and systems of care."}]', '[{"context": "On your own", "text": "Read this unit''s RACGP page and its primary guideline; list the last five patients from your practice who fit this unit and check your management against the guideline."}, {"context": "With your supervisor", "text": "Bring two recent cases from this unit to your tutorial; map your reasoning to the competency framework and ask for specific feedback."}, {"context": "