(41, 'contextual', 34, 'Travel medicine', 'https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/travel-medicine', 'Pre-travel risk assessment, vaccines, malaria prophylaxis, returned traveller.', 'Pre-travel risk assessment, vaccines, malaria prophylaxis, returned traveller.', '[{"domain": "D1 Communication and the patient-doctor relationship", "outcome": "Communicate clearly, respectfully and effectively; use health education and culturally safe communication; provide holistic, patient-centred care."}, {"domain": "D2 Applied professional knowledge and skills", "outcome": "Take a timely history, perform a relevant examination, form differentials, select and interpret investigations, reason clinically, prescribe safely and manage uncertainty."}, {"domain": "D3 Population health and the context of general practice", "outcome": "Apply epidemiology to screening and management, use resources sustainably, manage public health risks, and promote health equity."}, {"domain": "D4 Professional and ethical role", "outcome": "Practise ethically with duty of care, maintain professional conduct and boundaries, care for your own health, and contribute to teaching and quality."}, {"domain": "D5 Organisational and legal dimensions", "outcome": "Maintain accurate records, privacy and consent; work within medico-legal, quality and safety frameworks; manage time, priorities and systems of care."}]', '[{"context": "On your own", "text": "Read this unit''s RACGP page and its primary guideline; list the last five patients from your practice who fit this unit and check your management against the guideline."}, {"context": "With your supervisor", "text": "Bring two recent cases from this unit to your tutorial; map your reasoning to the competency framework and ask for specific feedback."}, {"context": "In a small group", "text": "Run a case-based discussion or role-play: one member presents a case from this unit, the group works the differential and management, then compare with the guideline."}, {"context": "With a non-medical person", "text": "Explain one core concept from this unit (e.g., why we screen, how the treatment works) in plain language to a friend or family member - teach-back tests your own understanding."}]', '["Pre-travel consult structure", "Vaccine planning including yellow fever certification", "Malaria prophylaxis and regions", "Travellers'' diarrhoea: prevention, self-treatment kit", "Returning traveller fever = emergency", "Special travellers: pregnant, immunosuppressed, kids", "Deep vein thrombosis risk on long flights"]', '', '[{"title": "CDC Yellow Book", "tier": 2, "url": "https://wwwnc.cdc.gov/travel", "source": "CDC Yellow Book"}, {"title": "WHO travel health", "tier": 3, "url": "https://www.who.int", "source": "WHO travel health"}]', '[{"label": "Travelvax", "url": "https://www.travelvax.com.au", "kind": "org", "source": "Travelvax"}]'),
(42, 'contextual', 35, 'Women''s health', 'https://www.racgp.org.au/education/education-providers/curriculum/curriculum-and-syllabus/units/womens-health', 'Cervical screening, menopause, PCOS, heavy menstrual bleeding, breast symptoms, contraception.', 'Cervical screening, menopause, PCOS, heavy menstrual bleeding, breast symptoms, contraception.', '[{"domain": "D1 Communication and the patient-doctor relationship", "outcome": "Communicate clearly, respectfully and effectively; use health education and culturally safe communication; provide holistic, patient-centred care."}, {"domain": "D2 Applied professional knowledge and skills", "outcome": "Take a timely history, perform a relevant examination, form differentials, select and interpret investigations, reason clinically, prescribe safely and manage uncertainty."}, {"domain": "D3 Population health and the context of general practice", "outcome": "Apply epidemiology to screening and management, use resources sustainably, manage public health risks, and promote health equity."}, {"domain": "D4 Professional and ethical role", "outcome": "Practise ethically with duty of care, maintain professional conduct and boundaries, care for your own health, and contribute to teaching and quality."}, {"domain": "D5 Organisational and legal dimensions", "outcome": "Maintain accurate records, privacy and consent; work within medico-legal, quality and safety frameworks; manage time, priorities and systems of care."}]', '[{"context": "On your own", "text": "Read this unit''s RACGP page and its primary guideline; list the last five patients from your practice who fit this unit and check your management against the guideline."}, {"context": "With your supervisor", "text": "Bring two recent cases from this unit to your tutorial; map your reasoning to the competency framework and ask for specific feedback."}, {"context": "In a small group", "text": "Run a case-based discussion or role-play: one member presents a case from this unit, the group works the differential and management, then compare with the guideline."}, {"context": "With a non-medical person", "text": "Explain one core concept from this unit (e.g., why we screen, how the treatment works) in plain language to a friend or family member - teach-back tests your own understanding."}]', '["Cervical screening: HPV, self-collection, result pathways", "Heavy menstrual bleeding: PALM-COEIN, treatment ladder", "Pelvic pain: endometriosis, PID", "Menopause and MHT: timing, risks, non-hormonal", "PCOS across the lifespan", "Breast symptoms and BreastScreen", "Urinary incontinence", "Osteoporosis prevention in women", "Premenstrual disorders"]', '', '[{"title": "NCSP guidelines", "tier": 1, "url": "https://screening.cancer.org.au/cervical/", "source": "NCSP guidelines"}, {"title": "Menopause resources (AMS)", "tier": 2, "url": "https://www.menopause.org.au", "source": "Menopause resources"}]', '[{"label": "BreastScreen Australia", "url": "https://www.breastscreen.org.au", "kind": "org", "source": "BreastScreen Australia"}]');

